import sys

def is_palindrome(n):
    if n < 0:
        return False
    original = n
    reversed_num = 0
    while n > 0:
        reversed_num = reversed_num * 10 + n % 10
        n //= 10
    return original == reversed_num

def main():
    line = sys.stdin.readline()
    n = int(line.strip())
    if is_palindrome(n):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
